REPLACE INTO `settings` (`skey`, `svalue`, `updated_at`) VALUES ('brand_accent','#ffcc00','2026-11-03 12:23:22'),('brand_primary','#0b0b0c','2026-11-03 11:59:30'),('bus_body','To make attending The Gathering seamless and accessible for everyone, complimentary buses will collect attendees each morning from designated pick-up locations across Ibadan.','2026-11-03 12:38:32'),('bus_dropoff','The Gathering International Christian Network, Mekun, Elebu Axis, Alao Akala Expressway, New Garage, Ibadan','2026-11-03 12:38:32'),('bus_fee','100% free, to and fro','2026-11-03 12:38:32'),('bus_heading','Join the bus: free to and fro','2026-11-03 12:38:32'),('bus_media_id','36','2026-11-03 12:38:32'),('bus_time','8:00 AM daily, 27–29 November','2026-11-03 12:38:32'),('contact_email','thegatheringcof@gmail.com','2026-11-03 12:51:04'),('contact_intro','Whether you seek prayer, guidance, or simply wish to learn more about our community, our doors and hearts are always open.','2026-11-03 11:45:54'),('contact_phone','+234 708 784 7372','2026-11-03 12:38:32'),('favicon_media_id','2','2026-11-03 11:45:54'),('footer_text','An annual interdenominational prayer conference committed to spiritual revival and community transformation. A Movement of Prayer, Compassion, Impact.','2026-11-03 11:45:54'),('form_contact_enabled','1','2026-11-03 12:51:09'),('form_newsletter_enabled','0','2026-11-03 12:50:58'),('form_partnership_enabled','1','2026-11-03 12:51:09'),('form_prayer_enabled','0','2026-11-03 12:50:58'),('form_registration_enabled','1','2026-11-03 12:51:09'),('form_testimony_enabled','0','2026-11-03 12:50:59'),('form_volunteer_enabled','0','2026-11-03 12:50:59'),('funding_note','Exchange rates are planning estimates. All giving is stewarded with integrity and accountability.','2026-11-03 12:38:32'),('funding_total','NGN: ₦133,000,000\nGBP: £83,125\nUSD: $110,833','2026-11-03 12:38:32'),('ga_measurement_id','','2026-11-03 11:45:12'),('giving_bank_details','','2026-11-03 11:45:12'),('giving_intro','','2026-11-03 11:45:12'),('giving_online_label','','2026-11-03 11:45:12'),('giving_online_url','','2026-11-03 11:45:12'),('google_site_verification','','2026-11-03 11:45:12'),('gtm_container_id','','2026-11-03 11:45:12'),('hero_media_id','15','2026-11-03 11:45:54'),('hero_summary','Annual interdenominational prayer and compassion conference. Reaching up to 5,000 people through medical and compassion outreach.','2026-11-03 12:38:32'),('land_body','Land has been secured in Ido Local Government Area, Oyo State, Nigeria. 1 acre has been secured within a 2.66-acre site as the first phase. Initial payments have been made and development has begun, with the orange tree stands protected and the water tank stand preserved. This investment is a foundation for future generations of impact.','2026-11-03 12:38:32'),('land_figure','2.66 acres','2026-11-03 11:45:54'),('land_figure_label','Total site in Ido LGA, Oyo State. 1 acre secured so far; development has begun.','2026-11-03 12:38:32'),('land_heading','The Gathering Land','2026-11-03 11:45:54'),('livestream_embed_url','','2026-11-03 11:45:12'),('livestream_is_live','0','2026-11-03 11:45:12'),('livestream_url','','2026-11-03 11:45:12'),('logo_light_media_id','1','2026-11-03 11:45:54'),('logo_media_id','1','2026-11-03 11:45:54'),('marquee_words','','2026-11-03 12:38:32'),('meta_description','The Gathering 2026: The Move of the Spirit; Breaking Territories. 27–29 November 2026, Ibadan, Oyo State, Nigeria. An annual interdenominational prayer and compassion conference.','2026-11-03 12:38:32'),('meta_pixel_id','','2026-11-03 11:45:12'),('mission_lines','Prayer must be accompanied by compassion.\nWorship must be followed by action.\nFaith must produce impact.','2026-11-03 11:45:54'),('notify_contact','','2026-11-03 11:45:12'),('notify_default','thegatheringcof@gmail.com','2026-11-03 11:45:54'),('notify_newsletter','','2026-11-03 11:45:12'),('notify_partnership','','2026-11-03 11:45:12'),('notify_prayer','','2026-11-03 11:45:12'),('notify_registration','','2026-11-03 11:45:12'),('notify_testimony','','2026-11-03 11:45:12'),('notify_volunteer','','2026-11-03 11:45:12'),('og_media_id','15','2026-11-03 11:45:54'),('org_legal','The Gathering International Christian Network, incorporated in the United Kingdom, Registration No: 15843980. An arm of The Chariot of Fire World Outreach (COFWO). Convener: Yomi Adeboye.','2026-11-03 12:56:28'),('parent_logo_media_id','3','2026-11-03 11:45:54'),('parent_org_name','The Chariot of Fire World Outreach (COFWO)','2026-11-03 11:45:54'),('parent_org_url','','2026-11-03 12:51:44'),('partner_body','Support prayer, compassion, and community impact in Nigeria.','2026-11-03 12:38:32'),('partner_heading','Stand with us in The Move of the Spirit','2026-11-03 12:38:32'),('partnership_docs_url','https://drive.google.com/drive/folders/17andQG8HPetyNSHIRYT59MVy0o8OkLdK','2026-11-03 12:38:32'),('postal_address','Purley Way, Croydon, London CR0 4RG','2026-11-03 11:45:54'),('programme_note','The full programme will be confirmed and updated by the ministry team.','2026-11-03 12:38:32'),('registration_confirm_note','','2026-11-03 11:45:12'),('show_attendee_count','0','2026-11-03 11:45:12'),('site_name','The Gathering','2026-11-03 11:45:12'),('site_tagline','Annual interdenominational prayer conference','2026-11-03 11:45:54'),('social_facebook','','2026-11-03 11:45:12'),('social_instagram','','2026-11-03 11:45:12'),('social_tiktok','','2026-11-03 11:45:12'),('social_x','','2026-11-03 11:45:12'),('social_youtube','https://www.youtube.com/@thegatheringcn','2026-11-03 11:45:54'),('volunteer_intro','','2026-11-03 11:45:12'),('volunteer_teams','','2026-11-03 12:50:59'),('welcome_body','<p>The Gathering is more than a conference. It is an annual call to prayer, revival, and transformation, bringing together ministers, families, and communities in pursuit of spiritual awakening and tangible compassion.</p><p>Each year, lives are touched through worship, the Word, healing prayer, community feeding, and medical outreach.</p><p>In 2026, under the theme “Breaking Territories,” we believe God is calling us to expand our impact, spiritually and practically, establishing a permanent foundation for future generations.</p>','2026-11-03 12:21:34'),('welcome_heading','A Movement Beyond an Event','2026-11-03 11:45:54'),('whatsapp_community_url','','2026-11-03 11:45:12'),('whatsapp_number','','2026-11-03 11:45:12'),('why_body','Across many communities in Nigeria, families face ongoing challenges. For many, opportunities for medical screening, basic medications, and community support are rare.\n\nThe Gathering responds to both spiritual and practical needs, creating an atmosphere of prayer while delivering tangible outreach.','2026-11-03 11:45:54'),('why_heading','Why The Gathering Matters','2026-11-03 11:45:54');
