ads/2026/11/dc521818577222f6.jpg','image','TG2.jpg','image/jpeg',139638,1600,1066,'480,960','Ministers standing in worship',NULL,'2026-11-03 11:45:41'),(23,'uploads/2026/11/4d2959514492a6d8.jpg','image','TG3.jpg','image/jpeg',133865,1600,1066,'480,960','A minister preaching from the pulpit',NULL,'2026-11-03 11:45:42'),(24,'uploads/2026/11/7f596fda66aded16.jpg','image','TG6.jpg','image/jpeg',221321,1600,976,'480,960','Attendees bowing in prayer',NULL,'2026-11-03 11:45:44'),(25,'uploads/2026/11/bbbdde1de07bd79c.jpg','image','TG7.jpg','image/jpeg',141804,1600,976,'480,960','A worshipper praying with hands together',NULL,'2026-11-03 11:45:45'),(26,'uploads/2026/11/83151f1b6392862f.jpg','image','TG9.jpg','image/jpeg',107553,1600,976,'480,960','A woman worshipping with both hands raised',NULL,'2026-11-03 11:45:46'),(27,'uploads/2026/11/1d49de5bd10e5840.jpg','image','TG10.jpg','image/jpeg',174822,1600,976,'480,960','A minister praying with attendees',NULL,'2026-11-03 11:45:47'),(28,'uploads/2026/11/68c3c4edfc3f91d4.jpg','image','TG11.jpg','image/jpeg',167164,1600,976,'480,960','Attendees in quiet prayer',NULL,'2026-11-03 11:45:48'),(29,'uploads/2026/11/bdaec318d6e49428.jpg','image','TG12.jpg','image/jpeg',157553,1600,976,'480,960','Attendees listening during a session',NULL,'2026-11-03 11:45:49'),(30,'uploads/2026/11/286392176a8d4a26.jpg','image','TG13.jpg','image/jpeg',177520,1600,976,'480,960','Attendees standing in prayer',NULL,'2026-11-03 11:45:50'),(31,'uploads/2026/11/9950c62afa114648.jpg','image','TG4.jpg','image/jpeg',79301,1600,1066,'480,960','A minister preaching with a microphone',NULL,'2026-11-03 11:45:51'),(32,'uploads/2026/11/b7bfe74e48220cc6.jpg','image','TG5.jpg','image/jpeg',89015,1365,2048,'480,960','A minister preaching with a microphone',NULL,'2026-11-03 11:45:53'),(35,'uploads/2026/11/751228f5674d94c2.jpg','image','speakers-lineup.jpg','image/jpeg',273503,1600,800,'480,960','The Gathering 2026 flyer: The Move of the Spirit; Breaking Territories, 27 to 29 November, with the ministers lineup',NULL,'2026-11-03 12:38:30'),(36,'uploads/2026/11/f50deff458e81431.jpg','image','join-the-bus.jpg','image/jpeg',182255,1339,1440,'480,960','Join the bus flyer: free buses to and from The Gathering, 27 to 29 November at 8 AM',NULL,'2026-11-03 12:38:31');
REPLACE INTO `events` (`id`, `name`, `theme`, `theme_scripture`, `starts_at`, `ends_at`, `venue_name`, `venue_address`, `map_query`, `summary`, `hero_media_id`, `flyer_media_id`, `programme_media_id`, `registration_open`, `capacity`, `is_current`, `created_at`, `updated_at`) VALUES (1,'The Gathering 2026','The Move of the Spirit','Breaking Territories','2026-11-27 00:00:00','2026-11-29 23:59:00','The Gathering International Christian Centre, Ibadan','Mekun, Elebu Axis, Alao Akala Expressway, New Garage, Ibadan, Oyo State, Nigeria','Elebu, Alao Akala Expressway, Ibadan, Oyo State, Nigeria','<p>The Gathering 2026 is an annual interdenominational prayer and compassion conference under the theme “The Move of the Spirit; Breaking Territories”. Three days of worship, the Word, healing prayer, medical outreach and community feeding, reaching up to 5,000 people.</p>',15,35,NULL,1,5,1,'2026-11-03 11:45:54','2026-11-03 12:50:40');
REPLACE INTO `pages` (`id`, `slug`, `title`, `intro`, `body`, `hero_media_id`, `meta_title`, `meta_description`, `is_system`, `is_published`, `created_at`, `updated_at`) VALUES (1,'about','About The Gathering','It is an annual call to prayer, revival, and transformation, bringing together ministers, families, and communities in pursuit of spiritual awakening and tangible compassion.','<h2>Who we are</h2>\n<p>The Gathering International Christian Network is an annual interdenominational prayer conference committed to spiritual revival and community transformation.</p>\n<p>Incorporated in the United Kingdom, Registration No: 15843980. An arm of The Chariot of Fire World Outreach (COFWO). Convener: Yomi Adeboye.</p>\n<p><strong>Our mission is simple:</strong> To inspire revival, impart truth, and empower communities, spiritually and practically.</p>\n<blockquote>We believe prayer must be accompanied by compassion. Worship must be followed by action. Faith must produce impact.</blockquote>\n<h2>Our vision</h2>\n<p>“Breaking Territories” is not only our 2026 theme, it is our mission. We envision:</p>\n<ul>\n<li>Expanding spiritual revival across communities</li>\n<li>Providing structured medical outreach to underserved families</li>\n<li>Feeding vulnerable households through Heart of Compassion</li>\n<li>Developing a permanent Gathering Land for long-term ministry</li>\n<li>Building infrastructure that supports future impact</li>\n</ul>\n<p>The Gathering Land in Ido LGA (2.66 acres) represents a long term investment in sustainable ministry and outreach. We are building not just for one year, but for generations.</p><h2>The convener</h2><p>Pastor Yomi Adeboye is the Convener of The Gathering International Christian Network and leads The Chariot of Fire World Outreach (COFWO).</p><h2>Governance &amp; transparency</h2><p>The Gathering is committed to integrity, accountability, and responsible stewardship of all resources.</p><ul><li>Financial oversight is provided by the leadership team.</li><li>Major expenditures are reviewed and approved internally.</li><li>Partners receive updates and impact reports following the event.</li><li>Documentation supporting key projects is maintained.</li></ul>',19,'About','The Gathering International Christian Network is an annual interdenominational prayer conference committed to spiritual revival and community transformation.',1,1,'2026-11-03 11:45:12','2026-11-03 12:38:32'),(2,'venue','Venue & travel','The Gathering 2026 takes place at The Gathering International Christian Centre, Ibadan, with free buses to and fro every day.',NULL,NULL,'Venue & travel','Venue, directions and free bus pick-up points for The Gathering 2026, 27–29 November, Ibadan, Oyo State, Nigeria.',1,1,'2026-11-03 11:45:12','2026-11-03 12:38:32'),(3,'give','Give & partner','Your support directly funds the front-line outreach programs and medical aid initiatives.',NULL,6,'Give','Partner with The Gathering: support medical outreach, compassion feeding and the permanent Gathering Land in Oyo State, Nigeria.',1,1,'2026-11-03 11:45:12','2026-11-03 11:45:54'),(4,'volunteer','Volunteer',NULL,NULL,NULL,NULL,NULL,1,0,'2026-11-03 11:45:12','2026-11-03 11:45:12'),(5,'privacy','Privacy policy','How The Gathering collects, uses and protects your personal information.','<h2>Who we are</h2>\n<p>This website is run by The Gathering International Christian Network, incorporated in the United Kingdom (Registration No. 15843980), an arm of The Chariot of Fire World Outreach (COFWO). You can contact us at thegatheringcof@gmail.com.</p>\n<h2>What we collect</h2>\n<p>We only collect the information you choose to give us through the forms on this website:</p>\n<ul><li><strong>Registration:</strong> your name, email address, phone number, city, church or ministry, the number of people attending and any notes you add.</li><li><strong>Contact and partnership enquiries:</strong> your name, email address, phone number (optional), organisation (optional) and your message.</li></ul>\n<p>To protect the website from abuse, we also store a scrambled (hashed) version of your IP address and your browser type with each submission.</p>\n<h2>How we use it</h2>\n<ul><li>To manage your registration for The Gathering and contact you about it.</li><li>To reply to your message or partnership enquiry.</li><li>To keep the website secure and prevent spam.</li></ul>\n<p>We do not sell your information or use it for unrelated marketing.</p>\n<h2>Who can see it</h2>\n<p>Only authorised members of our ministry team, through a password-protected admin area. Emails are sent through our email provider, and the website is hosted by Hostinger.</p>\n<h2>How long we keep it</h2>\n<p>We keep registration details for up to 12 months after the event, and enquiries for up to 24 months, unless the law requires us to keep them longer. After that they are deleted.</p>\n<h2>Your rights</h2>\n<p>You can ask to see, correct or delete the information we hold about you, or object to how we use it, by emailing thegatheringcof@gmail.com. You also have the right to complain to the UK Information Commissioner\'s Office (ico.org.uk).</p>\n<h2>Cookies</h2>\n<p>This website uses one essential cookie to keep forms secure. It does not use advertising or tracking cookies.</p>\n<p>Last updated: 3 November 2026</p>',NULL,'Privacy policy','How The Gathering International Christian Network collects, uses and protects personal information submitted through this website.',1,1,'2026-11-03 11:45:12','2026-11-03 12:21:49'),(6,'outreach','Fuel the mission','This is not just a conference. It is a strategic mobilization. Your support directly funds the front-line outreach programs and medical aid initiatives.','<h2>Infrastructure development</h2><p>To ensure that The Gathering can operate effectively and sustainably, several key infrastructure developments are planned for the land.</p>',8,'Outreach','The Gathering 2026 outreach: spiritual outreach, welfare outreach, medical aid for up to 5,000 people, and the 2.66-acre Gathering Land in Ido LGA, Oyo State.',1,1,'2026-11-03 11:45:12','2026-11-03 11:45:54');
REPLACE INTO `albums` (`id`, `slug`, `title`, `year`, `description`, `is_published`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'the-gathering-2025','The Gathering 2025',2025,NULL,1,10,'2026-11-03 11:45:14','2026-11-03 12:21:34'),(2,'worship-and-praise','Worship & Praise',NULL,NULL,1,20,'2026-11-03 11:45:31','2026-11-03 12:21:34'),(3,'prayer-and-ministry','Prayer & Ministry',NULL,NULL,1,30,'2026-11-03 11:45:39','2026-11-03 12:21:34');
