REPLACE INTO `blocks` (`id`, `grp`, `title`, `body`, `icon`, `media_id`, `sort_order`, `is_published`) VALUES (1,'stats','5,000+','Lives touched yearly',NULL,NULL,10,1),(2,'stats','13','Medical centre partners',NULL,NULL,20,1),(3,'stats','20,000+','Individuals blessed',NULL,NULL,30,1),(4,'pillars','Prayer & Worship','Uniting believers in worship, prayer, healing, and spiritual renewal, and experience deeper growth.','prayer',NULL,10,1),(5,'pillars','Medical Outreach','Providing free screenings, and essential medications to underserved communities.','medical',NULL,20,1),(6,'pillars','Compassion Outreach','Delivering food support and practical assistance to families facing hardship.','compassion',NULL,30,1),(7,'pillars','Community Transformation','Strengthening communities through sustainable outreach, unity, and long-term ministry initiatives.','community',NULL,40,1),(8,'challenges','Limited access to healthcare',NULL,'medical',NULL,10,1),(9,'challenges','Financial hardship and food insecurity',NULL,'compassion',NULL,20,1),(10,'challenges','Spiritual and emotional burdens',NULL,'prayer',NULL,30,1),(11,'challenges','Inadequate community infrastructure',NULL,'home',NULL,40,1),(12,'activities','Worship & Prayer Sessions','An atmosphere of intercession, revival, healing, and restoration.','prayer',NULL,10,1),(13,'activities','Heart of Compassion Outreach','Food distribution and practical support for vulnerable families.','compassion',NULL,20,1),(14,'activities','Medical Outreach','Basic health checks, medication distribution, and preventive care.','medical',NULL,30,1),(15,'activities','Family & Community Engagement','Encouraging unity, faith, and long-term transformation.','community',NULL,40,1),(16,'programmes','Spiritual Outreach','Disseminating the message of hope through large-scale events and personalized ministry teams. The Gathering is an annual interdenominational prayer conference committed to spiritual revival and tangible community transformation.','prayer',NU